  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtmsa__content .chattext {
  --tw-prose-code: var(--rtmsa-strong, var(--rtmsa-ink));
  --tw-prose-pre-code: var(--rtmsa-ink);
  --tw-prose-pre-bg: var(--rtmsa-tint);
  max-width: none;
  color: var(--rtmsa-ink);
  font-size: var(--rtmsa-font-size) !important;
  line-height: var(--rtmsa-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtmsa__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtmsa-font-size);
  line-height: var(--rtmsa-line-height);
}
.rtmsa__content :where(p) { margin: 0 0 var(--rtmsa-para-gap); }
.rtmsa__content :where(p:last-child) { margin-bottom: 0; }
.rtmsa__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsa-font-display);
  margin: 1.35em 0 .55em;
