/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtmsa__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtmsa-muted);
  --color-textcolor2: var(--rtmsa-muted);
  --color-textcolor: var(--rtmsa-ink);
  --color-darkborderc: var(--rtmsa-line);
  --color-darkbutton: var(--rtmsa-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtmsa-muted);
}
.rtmsa__info, .rtmsa__actions { min-width: 0; max-width: 100%; }
.rtmsa__info > div, .rtmsa__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtmsa-muted); }
.rtmsa__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtmsa__info button.transition-all,
.rtmsa__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtmsa__info button.transition-all:hover,
.rtmsa__actions button[class*="button-icon-"]:hover { background: var(--rtmsa-tint); color: var(--rtmsa-ink); }
.rtmsa__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtmsa-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtmsa__info button:not(.transition-all):hover { background: var(--rtmsa-tint); color: var(--rtmsa-ink); }
.rtmsa :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtmsa-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtmsa__portrait { overflow: hidden; background: var(--rtmsa-tint); }
.rtmsa__portrait > * {
  width: 100% !important;
