  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtmsa-bg-fill);
  border: var(--rtmsa-bg-border, 0);
  -webkit-backdrop-filter: var(--rtmsa-blur);
