/* 구조: 메신저 한쪽 */

.rtmsa { background: var(--rtmsa-wall); padding: .5rem clamp(.75rem, 3vw, 1.5rem); }
.rtmsa__row { display: flex; align-items: flex-start; gap: .65rem; max-width: 52rem; margin: 0 auto; }
.rtmsa__avatar { flex: 0 0 auto; width: var(--rtmsa-avatar); aspect-ratio: 1; }
.rtmsa__portrait {
  width: 100%;
  height: 100%;
  padding: 2px;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--rtmsa-accent), var(--rtmsa-frame));
  box-shadow: 0 3px 10px var(--rtmsa-shadow);
}
.rtmsa__main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; }
.rtmsa__name { margin: .1rem .25rem .32rem; color: var(--rtmsa-muted); font-size: .8em; font-weight: 600; }
.rtmsa__bubble {
  position: relative;
  max-width: min(100%, 36em);
  padding: .8em 1.15em;
  border: 1px solid var(--rtmsa-line);
  border-radius: 1.15rem;
  border-top-left-radius: .3rem;
  box-shadow: 0 4px 14px var(--rtmsa-shadow);
}
.rtmsa .rtmsa__bg { background: var(--rtmsa-bg-sheen), var(--rtmsa-panel); }
.rtmsa--user .rtmsa__bg { background: var(--rtmsa-bg-sheen), var(--rtmsa-panel-user); }
.rtmsa__footer { margin: .28rem .2rem 0; font-size: .82em; }
.rtmsa--user .rtmsa__row { flex-direction: row-reverse; }
.rtmsa--user .rtmsa__main { align-items: flex-end; }
.rtmsa--user .rtmsa__bubble { border-radius: 1.15rem; border-top-right-radius: .3rem; }
.rtmsa--user .rtmsa__footer { justify-content: flex-end; }
@media (max-width: 560px) { .rtmsa__bubble { max-width: 100%; } }

/* 짧은 대화: 맨 위 메시지 위쪽 빈 곳도 같은 바탕으로 칠합니다. */
.default-chat-screen > .risu-chat .rtmsa,
.chat-message-container:last-child .rtmsa { box-shadow: 0 -100vh 0 100vh var(--rtmsa-wall); }
/* 첫인사 위에 RisuAI가 붙이는 안내문(AI 생성 안내, 제작자 메모)이 칠한 바탕 아래로 숨지 않게 합니다. */
:where(.default-chat-screen > .risu-chat:has(.rtmsa) ~ *) { position: relative; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (글래스) ── */
.rtmsa {
  --rtmsa-blur: blur(16px) saturate(1.3);
  --rtmsa-bg-sheen: radial-gradient(120% 80% at 0% 0%, rgba(255, 255, 255, .13), transparent 54%), linear-gradient(165deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015) 68%);
  --rtmsa-bg-edge: 0 14px 36px -14px rgba(0, 0, 0, .52), inset 0 1px 0 rgba(255, 255, 255, .24), inset 0 0 0 1px rgba(255, 255, 255, .13);
  --rtmsa-bg-fallback: rgba(16, 18, 26, .88);
  --rtmsa-wall: transparent;
  --rtmsa-panel: rgba(15, 18, 26, .42);
  --rtmsa-panel-user: rgba(28, 31, 42, .44);
  --rtmsa-ink: #eef1f6;
  --rtmsa-strong: #ffffff;
  --rtmsa-muted: rgba(228, 231, 238, .68);
  --rtmsa-accent: #e2cea9;
  --rtmsa-dialog: #ffffff;
  --rtmsa-frame: rgba(255, 255, 255, .2);
  --rtmsa-shadow: rgba(0, 0, 0, .28);
  --rtmsa-line: rgba(255, 255, 255, .14);
  --rtmsa-tint: rgba(255, 255, 255, .08);
  --rtmsa-edit-bg: rgba(10, 12, 18, .52);
}

@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlty-font-size로 바꿉니다. */
.rtlty {
  --rtlty-bg-fill: transparent;
  --rtlty-bg-border: 0;
  --rtlty-blur: none;
  --rtlty-bg-edge: none;
  --rtlty-bg-sheen: linear-gradient(transparent, transparent);
  --rtlty-bg-fallback: transparent;
  --rtlty-font-body: "Gowun Batang", "Noto Serif KR", serif;
  --rtlty-font-display: "Nanum Pen Script", "Gowun Batang", cursive;
  --rtlty-font-size: 16px;
  --rtlty-line-height: 1.9;
  --rtlty-para-gap: 0;
  --rtlty-dialog-weight: 700;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtlty {
  --risu-font-family: var(--rtlty-font-body);
  --FontColorStandard: var(--rtlty-ink);
  --FontColorBold: var(--rtlty-strong, var(--rtlty-ink));
  --FontColorItalic: var(--rtlty-muted);
  --FontColorItalicBold: var(--rtlty-muted);
  --FontColorQuote1: var(--rtlty-muted);
  --FontColorQuote2: var(--rtlty-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-body);
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
  letter-spacing: var(--rtlty-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtlty, .rtlty *, .rtlty *::before, .rtlty *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtlty.rtlty { display: block; }
.rtlty ::selection { background: color-mix(in srgb, var(--rtlty-accent) 26%, transparent); color: inherit; }
.rtlty__content {
  min-width: 0;
  color: var(--rtlty-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtlty__content .chattext {
  --tw-prose-code: var(--rtlty-strong, var(--rtlty-ink));
  --tw-prose-pre-code: var(--rtlty-ink);
  --tw-prose-pre-bg: var(--rtlty-tint);
  max-width: none;
  color: var(--rtlty-ink);
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtlty__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty__content :where(p) { margin: 0 0 var(--rtlty-para-gap); }
.rtlty__content :where(p:last-child) { margin-bottom: 0; }
.rtlty__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtlty-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtlty-strong, var(--rtlty-ink));
  font-family: var(--rtlty-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtlty__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtlty__content :where(h1) { font-size: calc(var(--rtlty-font-size) * 1.55); }
.rtlty__content :where(h2) { font-size: calc(var(--rtlty-font-size) * 1.32); }
.rtlty__content :where(h3) { font-size: calc(var(--rtlty-font-size) * 1.15); }
.rtlty__content :where(h4, h5, h6) { font-size: var(--rtlty-font-size); color: var(--rtlty-muted); }
.rtlty__content :where(strong) { font-weight: 700; color: var(--rtlty-strong, var(--rtlty-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtlty__content :where(em) { font-style: normal; color: var(--rtlty-muted); }
.rtlty__content mark[risu-mark="quote1"],
.rtlty__content mark[risu-mark="blockquote1"] { color: var(--rtlty-muted); background: transparent; }
.rtlty__content mark[risu-mark="quote2"],
.rtlty__content mark[risu-mark="blockquote2"] {
  color: var(--rtlty-dialog);
  font-weight: var(--rtlty-dialog-weight);
  background: transparent;
}
.rtlty__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtlty-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtlty-tint);
  color: var(--rtlty-muted);
}
.rtlty__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtlty__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtlty-ink); }
.rtlty__content :where(li)::marker { color: var(--rtlty-accent); }
.rtlty__content :where(a) {
  color: var(--rtlty-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtlty-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtlty__content :where(a:hover) { text-decoration-color: currentColor; }
.rtlty__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtlty-line) 15%, var(--rtlty-line) 85%, transparent);
}
.rtlty__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtlty-strong, var(--rtlty-ink));
  background: var(--rtlty-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.5;
}
.rtlty__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  border: 1px solid var(--rtlty-line);
  border-radius: .5rem;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.55;
}
.rtlty__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtlty__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtlty__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtlty-ink);
  border-bottom: 1px solid var(--rtlty-line);
  text-align: left;
  vertical-align: top;
}
.rtlty__content :where(th) {
  background: var(--rtlty-tint);
  color: var(--rtlty-strong, var(--rtlty-ink));
  font-weight: 600;
}
.rtlty__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtlty__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtlty-ink) !important;
  background: var(--rtlty-edit-bg) !important;
  border: 1px solid var(--rtlty-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtlty__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtlty-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtlty-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtlty__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtlty-muted);
  --color-textcolor2: var(--rtlty-muted);
  --color-textcolor: var(--rtlty-ink);
  --color-darkborderc: var(--rtlty-line);
  --color-darkbutton: var(--rtlty-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtlty-muted);
}
.rtlty__info, .rtlty__actions { min-width: 0; max-width: 100%; }
.rtlty__info > div, .rtlty__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtlty-muted); }
.rtlty__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtlty__info button.transition-all,
.rtlty__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtlty__info button.transition-all:hover,
.rtlty__actions button[class*="button-icon-"]:hover { background: var(--rtlty-tint); color: var(--rtlty-ink); }
.rtlty__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtlty-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtlty__info button:not(.transition-all):hover { background: var(--rtlty-tint); color: var(--rtlty-ink); }
.rtlty :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtlty-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlty__portrait { overflow: hidden; background: var(--rtlty-tint); }
.rtlty__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtlty, .rtlty * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtlty .rtlty__bg {
    background: var(--rtlty-bg-fallback, var(--rtlty-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtlty .rtlty__bg { background: var(--rtlty-bg-fallback, var(--rtlty-bg-fill)); }
}

.rtlty__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlty-bg-fill);
  border: var(--rtlty-bg-border, 0);
  -webkit-backdrop-filter: var(--rtlty-blur);
  backdrop-filter: var(--rtlty-blur);
  box-shadow: var(--rtlty-bg-edge);
}

/* 구조: 편지 양쪽 */


.rtlty {
  --rtlty-col: 44rem;
  --rtlty-gap: clamp(1rem, 2.2vw, 1.8rem);
  --rtlty-edge: 1rem;
  --rtlty-fixed-bottom: 5rem;
  --rtlty-fixed-w: max(8rem, min(calc((100% - var(--rtlty-col)) / 2 - var(--rtlty-gap) - var(--rtlty-edge)), calc((100vh - var(--rtlty-edge) - var(--rtlty-fixed-bottom)) * 3 / 4)));
  --rtlty-pad: .65rem;
  max-width: var(--rtlty-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtlty__side { display: none; }
.rtlty__main { position: relative; min-width: 0; }
.rtlty__speaker {
  display: flex;
  align-items: center;
  gap: .45rem;
  margin-bottom: .55rem;
  color: var(--rtlty-muted);
  font-size: .82em;
  font-weight: 700;
  letter-spacing: .02em;
}
.rtlty--char .rtlty__speaker { color: var(--rtlty-strong, var(--rtlty-ink)); }
.rtlty .x-risu-rtlty-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
.rtlty .x-risu-rtlty-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtlty) { transform: translateZ(0); }

/* PC: 1040px 이상에서만 양옆 고정 초상을 띄우고 가운데 열과 겹치지 않게 폭을 확보합니다. */
@media (min-width: 1040px) {
  .rtlty { --rtlty-col: min(44rem, calc(100% - 22rem)); }
  .chat-message-container:first-child .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    margin-block: auto;
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-char,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-pair-char {
    left: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-char));
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-user,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-pair-user {
    right: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-user));
  }
  .chat-message-container:first-child .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--char .x-risu-rtlty-pair-char,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child .rtlty--user .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--user .x-risu-rtlty-pair-user,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty--user .x-risu-rtlty-pair-user {
    translate: 0 -4px;
    scale: 1.018;
    filter: drop-shadow(0 16px 14px rgba(0, 0, 0, .24));
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-fade {
    /* 왼쪽 초상과 똑같은 칸을 투명하게 겹쳐 두고 그 왼쪽 위 모서리에 단추를 놓습니다.
       앵커 위치 지정이 없는 브라우저(Firefox, 이전 Safari)에서도 단추가 초상에서 떨어지지 않습니다. */
    display: block;
    position: fixed;
    z-index: 2;
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    left: var(--rtlty-edge);
    width: var(--rtlty-fixed-w);
