.rtlty__footer { margin-top: .75rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlty__content :where(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlty-font-body); font-family: var(--rtlty-font-body); }
@media (max-width: 1039px) {
  .rtlty__frame { padding: 4px; }
