}

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (미색) ── */
.rtlty {
  --rtlty-paper: #faf6ed;
  --rtlty-paper-user: #f3ece0;
  --rtlty-rule: rgba(175, 152, 122, .24);
  --rtlty-ink: #3a3128;
  --rtlty-strong: #221b14;
  --rtlty-muted: #847664;
  --rtlty-accent: #946444;
  --rtlty-dialog: #724226;
  --rtlty-stamp: #fffdf7;
