  --FontColorQuote2: var(--rtlty-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-body);
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
  letter-spacing: var(--rtlty-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
