.rtlty__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtlty__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtlty-ink); }
.rtlty__content :where(li)::marker { color: var(--rtlty-accent); }
.rtlty__content :where(a) {
