  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtlty__info button.transition-all:hover,
.rtlty__actions button[class*="button-icon-"]:hover { background: var(--rtlty-tint); color: var(--rtlty-ink); }
.rtlty__info button:not(.transition-all) {
