.rtlty__info button:not(.transition-all):hover { background: var(--rtlty-tint); color: var(--rtlty-ink); }
.rtlty :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtlty-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlty__portrait { overflow: hidden; background: var(--rtlty-tint); }
