@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtlty .rtlty__bg { background: var(--rtlty-bg-fallback, var(--rtlty-bg-fill)); }
}

.rtlty__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlty-bg-fill);
