  -webkit-backdrop-filter: var(--rtlty-blur);
  backdrop-filter: var(--rtlty-blur);
  box-shadow: var(--rtlty-bg-edge);
}

/* 구조: 편지 양쪽 */


.rtlty {
  --rtlty-col: 44rem;
