.rtlty .x-risu-rtlty-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
.rtlty .x-risu-rtlty-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtlty) { transform: translateZ(0); }

/* PC: 1040px 이상에서만 양옆 고정 초상을 띄우고 가운데 열과 겹치지 않게 폭을 확보합니다. */
@media (min-width: 1040px) {
  .rtlty { --rtlty-col: min(44rem, calc(100% - 22rem)); }
  .chat-message-container:first-child .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    margin-block: auto;
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-char,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-pair-char {
    left: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-char));
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-user,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-pair-user {
    right: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-user));
  }
  .chat-message-container:first-child .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--char .x-risu-rtlty-pair-char,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child .rtlty--user .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--user .x-risu-rtlty-pair-user,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty--user .x-risu-rtlty-pair-user {
    translate: 0 -4px;
    scale: 1.018;
    filter: drop-shadow(0 16px 14px rgba(0, 0, 0, .24));
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-fade {
    /* 왼쪽 초상과 똑같은 칸을 투명하게 겹쳐 두고 그 왼쪽 위 모서리에 단추를 놓습니다.
       앵커 위치 지정이 없는 브라우저(Firefox, 이전 Safari)에서도 단추가 초상에서 떨어지지 않습니다. */
    display: block;
    position: fixed;
    z-index: 2;
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    left: var(--rtlty-edge);
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    margin: auto 0;
    padding: .6rem;
    pointer-events: none;
  }
  .rtlty .x-risu-rtlty-fade > summary {
    pointer-events: auto;
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .34);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .28);
    opacity: .72;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtlty .x-risu-rtlty-fade > summary::-webkit-details-marker { display: none; }
  .rtlty .x-risu-rtlty-fade > summary::before { content: "◐"; }
  .rtlty .x-risu-rtlty-fade > summary:hover,
  .rtlty .x-risu-rtlty-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .54); }
  .rtlty.rtlty .x-risu-rtlty-pair.x-risu-rtlty-pair:has(> .x-risu-rtlty-fade[open]) :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰·좁은 창: 메시지마다 위에 두 초상이 마주 보고, 반대편 초상이 빈 액자 위에 정확히 겹칩니다. */
@media (max-width: 1039px) {
  .rtlty.rtlty { display: grid; }
  .rtlty {
    --rtlty-side-w: clamp(4.6rem, 16vw, 6rem);
    --rtlty-row-gap: .85rem;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    row-gap: var(--rtlty-row-gap);
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtlty-pad) 0;
  }
  .rtlty__side { display: flex; flex-direction: row; align-items: center; gap: .55rem; min-width: 0; }
  .rtlty__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtlty__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtlty__frame { position: relative; width: var(--rtlty-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtlty__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtlty__side-name { min-width: 0; color: var(--rtlty-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtlty__main { grid-column: 1 / -1; grid-row: 2; min-width: 0; max-width: 100%; }
  .rtlty__speaker { display: none; }
  .rtlty--char .rtlty__side--char .rtlty__side-name, .rtlty--user .rtlty__side--user .rtlty__side-name { color: var(--rtlty-strong, var(--rtlty-ink)); }
  .rtlty--char .rtlty__side--char .rtlty__frame, .rtlty--user .rtlty__side--user .rtlty__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 8px rgba(0, 0, 0, .22));
  }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
    position: absolute;
    z-index: 2;
    bottom: calc(100% + var(--rtlty-row-gap) + 1px);
    width: var(--rtlty-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtlty--user .x-risu-rtlty-pair-char { display: block; left: 0; }
  .rtlty--char .x-risu-rtlty-pair-user { display: block; right: 0; }
}
/* 우표 액자: 어떤 배경 위에서도 깔끔한 톱니 우표 테두리 */
.rtlty__frame {
  padding: 6px;
  background: var(--rtlty-stamp);
  border: 1px solid var(--rtlty-line);
  border-radius: 3px;
  outline: 1px dashed color-mix(in srgb, var(--rtlty-muted) 42%, transparent);
  outline-offset: -3px;
  box-shadow: 0 5px 14px var(--rtlty-shadow);
  transform: rotate(var(--rtlty-tilt-char));
}
.rtlty__side--user .rtlty__frame { transform: rotate(var(--rtlty-tilt-user)); }
.rtlty { --rtlty-tilt-char: -1.6deg; --rtlty-tilt-user: 1.6deg; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  border: 6px solid var(--rtlty-stamp);
  border-radius: 3px;
  background-clip: padding-box;
  outline: 1px dashed color-mix(in srgb, var(--rtlty-muted) 42%, transparent);
  outline-offset: -3px;
  box-shadow: 0 10px 24px var(--rtlty-shadow);
}
@media (max-width: 1039px) {
  .rtlty .x-risu-rtlty-pair-char { transform: rotate(var(--rtlty-tilt-char)); }
  .rtlty .x-risu-rtlty-pair-user { transform: rotate(var(--rtlty-tilt-user)); }
}
.rtlty__side-name {
  font-family: var(--rtlty-font-display);
  font-size: 1.2em;
  font-weight: 400;
  padding: 0 .6em;
  border-radius: .2rem;
  border: 1px solid var(--rtlty-line);
  background: var(--rtlty-paper);
  color: var(--rtlty-strong, var(--rtlty-ink));
  box-shadow: 0 2px 6px var(--rtlty-shadow);
}
.rtlty__main {
  padding: 1.3rem clamp(1.05rem, 3.2vw, 1.9rem) .95rem;
  border: 1px solid var(--rtlty-line);
  border-radius: .35rem;
  box-shadow: 0 2px 6px var(--rtlty-shadow), 0 12px 28px var(--rtlty-shadow);
}
.rtlty .rtlty__bg {
  background-image:
    var(--rtlty-bg-sheen),
    repeating-linear-gradient(to bottom, transparent 0, transparent calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height)));
  background-color: var(--rtlty-paper);
  background-position: 0 0, 0 1.3rem;
}
.rtlty--user .rtlty__bg { background-color: var(--rtlty-paper-user); }
.rtlty__speaker {
  padding-bottom: .4rem;
  border-bottom: 1px solid var(--rtlty-line);
  font-family: var(--rtlty-font-display);
  font-size: 1.15em;
  font-weight: 400;
}
.rtlty__footer { margin-top: .75rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlty__content :where(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlty-font-body); font-family: var(--rtlty-font-body); }
@media (max-width: 1039px) {
  .rtlty__frame { padding: 4px; }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user { border-width: 4px; }
}

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (크라프트지) ── */
.rtlty {
  --rtlty-paper: #d8c19e;
  --rtlty-paper-user: #ceb58f;
  --rtlty-rule: rgba(110, 82, 48, .2);
  --rtlty-ink: #312418;
  --rtlty-strong: #1d140c;
  --rtlty-muted: #69533b;
  --rtlty-accent: #6b4022;
  --rtlty-dialog: #522e14;
  --rtlty-stamp: #f5ebd8;
  --rtlty-shadow: rgba(55, 36, 14, .22);
  --rtlty-line: #bba077;
  --rtlty-tint: #cbb48c;
  --rtlty-edit-bg: #e7d6b9;
}

@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlty-font-size로 바꿉니다. */
.rtlty {
  --rtlty-bg-fill: transparent;
  --rtlty-bg-border: 0;
  --rtlty-blur: none;
  --rtlty-bg-edge: none;
  --rtlty-bg-sheen: linear-gradient(transparent, transparent);
  --rtlty-bg-fallback: transparent;
  --rtlty-font-body: "Gowun Batang", "Noto Serif KR", serif;
  --rtlty-font-display: "Nanum Pen Script", "Gowun Batang", cursive;
  --rtlty-font-size: 16px;
  --rtlty-line-height: 1.9;
  --rtlty-para-gap: 0;
  --rtlty-dialog-weight: 700;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtlty {
  --risu-font-family: var(--rtlty-font-body);
  --FontColorStandard: var(--rtlty-ink);
  --FontColorBold: var(--rtlty-strong, var(--rtlty-ink));
  --FontColorItalic: var(--rtlty-muted);
  --FontColorItalicBold: var(--rtlty-muted);
  --FontColorQuote1: var(--rtlty-muted);
  --FontColorQuote2: var(--rtlty-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-body);
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
  letter-spacing: var(--rtlty-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtlty, .rtlty *, .rtlty *::before, .rtlty *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtlty.rtlty { display: block; }
.rtlty ::selection { background: color-mix(in srgb, var(--rtlty-accent) 26%, transparent); color: inherit; }
.rtlty__content {
  min-width: 0;
  color: var(--rtlty-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtlty__content .chattext {
  --tw-prose-code: var(--rtlty-strong, var(--rtlty-ink));
  --tw-prose-pre-code: var(--rtlty-ink);
  --tw-prose-pre-bg: var(--rtlty-tint);
  max-width: none;
  color: var(--rtlty-ink);
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtlty__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty__content :where(p) { margin: 0 0 var(--rtlty-para-gap); }
.rtlty__content :where(p:last-child) { margin-bottom: 0; }
.rtlty__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtlty-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtlty-strong, var(--rtlty-ink));
  font-family: var(--rtlty-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtlty__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtlty__content :where(h1) { font-size: calc(var(--rtlty-font-size) * 1.55); }
.rtlty__content :where(h2) { font-size: calc(var(--rtlty-font-size) * 1.32); }
.rtlty__content :where(h3) { font-size: calc(var(--rtlty-font-size) * 1.15); }
.rtlty__content :where(h4, h5, h6) { font-size: var(--rtlty-font-size); color: var(--rtlty-muted); }
.rtlty__content :where(strong) { font-weight: 700; color: var(--rtlty-strong, var(--rtlty-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtlty__content :where(em) { font-style: normal; color: var(--rtlty-muted); }
.rtlty__content mark[risu-mark="quote1"],
.rtlty__content mark[risu-mark="blockquote1"] { color: var(--rtlty-muted); background: transparent; }
.rtlty__content mark[risu-mark="quote2"],
.rtlty__content mark[risu-mark="blockquote2"] {
  color: var(--rtlty-dialog);
  font-weight: var(--rtlty-dialog-weight);
  background: transparent;
}
.rtlty__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtlty-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtlty-tint);
  color: var(--rtlty-muted);
}
.rtlty__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtlty__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtlty-ink); }
.rtlty__content :where(li)::marker { color: var(--rtlty-accent); }
.rtlty__content :where(a) {
  color: var(--rtlty-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtlty-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtlty__content :where(a:hover) { text-decoration-color: currentColor; }
.rtlty__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtlty-line) 15%, var(--rtlty-line) 85%, transparent);
}
.rtlty__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtlty-strong, var(--rtlty-ink));
  background: var(--rtlty-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.5;
}
.rtlty__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  border: 1px solid var(--rtlty-line);
  border-radius: .5rem;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.55;
}
.rtlty__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtlty__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtlty__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtlty-ink);
  border-bottom: 1px solid var(--rtlty-line);
  text-align: left;
  vertical-align: top;
}
.rtlty__content :where(th) {
  background: var(--rtlty-tint);
  color: var(--rtlty-strong, var(--rtlty-ink));
  font-weight: 600;
}
.rtlty__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtlty__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtlty-ink) !important;
  background: var(--rtlty-edit-bg) !important;
  border: 1px solid var(--rtlty-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtlty__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtlty-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtlty-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtlty__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtlty-muted);
  --color-textcolor2: var(--rtlty-muted);
  --color-textcolor: var(--rtlty-ink);
  --color-darkborderc: var(--rtlty-line);
  --color-darkbutton: var(--rtlty-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtlty-muted);
}
.rtlty__info, .rtlty__actions { min-width: 0; max-width: 100%; }
.rtlty__info > div, .rtlty__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtlty-muted); }
.rtlty__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtlty__info button.transition-all,
.rtlty__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtlty__info button.transition-all:hover,
.rtlty__actions button[class*="button-icon-"]:hover { background: var(--rtlty-tint); color: var(--rtlty-ink); }
.rtlty__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtlty-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtlty__info button:not(.transition-all):hover { background: var(--rtlty-tint); color: var(--rtlty-ink); }
.rtlty :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtlty-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlty__portrait { overflow: hidden; background: var(--rtlty-tint); }
.rtlty__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtlty, .rtlty * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtlty .rtlty__bg {
    background: var(--rtlty-bg-fallback, var(--rtlty-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtlty .rtlty__bg { background: var(--rtlty-bg-fallback, var(--rtlty-bg-fill)); }
}

.rtlty__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlty-bg-fill);
  border: var(--rtlty-bg-border, 0);
  -webkit-backdrop-filter: var(--rtlty-blur);
  backdrop-filter: var(--rtlty-blur);
  box-shadow: var(--rtlty-bg-edge);
}

/* 구조: 편지 양쪽 */


.rtlty {
  --rtlty-col: 44rem;
  --rtlty-gap: clamp(1rem, 2.2vw, 1.8rem);
  --rtlty-edge: 1rem;
  --rtlty-fixed-bottom: 5rem;
  --rtlty-fixed-w: max(8rem, min(calc((100% - var(--rtlty-col)) / 2 - var(--rtlty-gap) - var(--rtlty-edge)), calc((100vh - var(--rtlty-edge) - var(--rtlty-fixed-bottom)) * 3 / 4)));
  --rtlty-pad: .65rem;
  max-width: var(--rtlty-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtlty__side { display: none; }
.rtlty__main { position: relative; min-width: 0; }
.rtlty__speaker {
  display: flex;
  align-items: center;
  gap: .45rem;
  margin-bottom: .55rem;
  color: var(--rtlty-muted);
  font-size: .82em;
  font-weight: 700;
  letter-spacing: .02em;
}
.rtlty--char .rtlty__speaker { color: var(--rtlty-strong, var(--rtlty-ink)); }
.rtlty .x-risu-rtlty-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
.rtlty .x-risu-rtlty-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtlty) { transform: translateZ(0); }

/* PC: 1040px 이상에서만 양옆 고정 초상을 띄우고 가운데 열과 겹치지 않게 폭을 확보합니다. */
@media (min-width: 1040px) {
  .rtlty { --rtlty-col: min(44rem, calc(100% - 22rem)); }
  .chat-message-container:first-child .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    margin-block: auto;
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-char,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-pair-char {
    left: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-char));
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-user,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-pair-user {
    right: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-user));
  }
  .chat-message-container:first-child .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--char .x-risu-rtlty-pair-char,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child .rtlty--user .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--user .x-risu-rtlty-pair-user,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty--user .x-risu-rtlty-pair-user {
    translate: 0 -4px;
    scale: 1.018;
    filter: drop-shadow(0 16px 14px rgba(0, 0, 0, .24));
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-fade {
    /* 왼쪽 초상과 똑같은 칸을 투명하게 겹쳐 두고 그 왼쪽 위 모서리에 단추를 놓습니다.
       앵커 위치 지정이 없는 브라우저(Firefox, 이전 Safari)에서도 단추가 초상에서 떨어지지 않습니다. */
    display: block;
    position: fixed;
    z-index: 2;
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    left: var(--rtlty-edge);
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    margin: auto 0;
    padding: .6rem;
    pointer-events: none;
  }
  .rtlty .x-risu-rtlty-fade > summary {
    pointer-events: auto;
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .34);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .28);
    opacity: .72;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtlty .x-risu-rtlty-fade > summary::-webkit-details-marker { display: none; }
  .rtlty .x-risu-rtlty-fade > summary::before { content: "◐"; }
  .rtlty .x-risu-rtlty-fade > summary:hover,
  .rtlty .x-risu-rtlty-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .54); }
  .rtlty.rtlty .x-risu-rtlty-pair.x-risu-rtlty-pair:has(> .x-risu-rtlty-fade[open]) :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰·좁은 창: 메시지마다 위에 두 초상이 마주 보고, 반대편 초상이 빈 액자 위에 정확히 겹칩니다. */
@media (max-width: 1039px) {
  .rtlty.rtlty { display: grid; }
  .rtlty {
    --rtlty-side-w: clamp(4.6rem, 16vw, 6rem);
    --rtlty-row-gap: .85rem;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    row-gap: var(--rtlty-row-gap);
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtlty-pad) 0;
  }
  .rtlty__side { display: flex; flex-direction: row; align-items: center; gap: .55rem; min-width: 0; }
  .rtlty__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtlty__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtlty__frame { position: relative; width: var(--rtlty-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtlty__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtlty__side-name { min-width: 0; color: var(--rtlty-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtlty__main { grid-column: 1 / -1; grid-row: 2; min-width: 0; max-width: 100%; }
  .rtlty__speaker { display: none; }
  .rtlty--char .rtlty__side--char .rtlty__side-name, .rtlty--user .rtlty__side--user .rtlty__side-name { color: var(--rtlty-strong, var(--rtlty-ink)); }
  .rtlty--char .rtlty__side--char .rtlty__frame, .rtlty--user .rtlty__side--user .rtlty__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 8px rgba(0, 0, 0, .22));
  }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
    position: absolute;
    z-index: 2;
    bottom: calc(100% + var(--rtlty-row-gap) + 1px);
    width: var(--rtlty-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtlty--user .x-risu-rtlty-pair-char { display: block; left: 0; }
  .rtlty--char .x-risu-rtlty-pair-user { display: block; right: 0; }
}
/* 우표 액자: 어떤 배경 위에서도 깔끔한 톱니 우표 테두리 */
.rtlty__frame {
  padding: 6px;
  background: var(--rtlty-stamp);
  border: 1px solid var(--rtlty-line);
  border-radius: 3px;
  outline: 1px dashed color-mix(in srgb, var(--rtlty-muted) 42%, transparent);
  outline-offset: -3px;
  box-shadow: 0 5px 14px var(--rtlty-shadow);
  transform: rotate(var(--rtlty-tilt-char));
}
.rtlty__side--user .rtlty__frame { transform: rotate(var(--rtlty-tilt-user)); }
.rtlty { --rtlty-tilt-char: -1.6deg; --rtlty-tilt-user: 1.6deg; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  border: 6px solid var(--rtlty-stamp);
  border-radius: 3px;
  background-clip: padding-box;
  outline: 1px dashed color-mix(in srgb, var(--rtlty-muted) 42%, transparent);
  outline-offset: -3px;
  box-shadow: 0 10px 24px var(--rtlty-shadow);
}
@media (max-width: 1039px) {
  .rtlty .x-risu-rtlty-pair-char { transform: rotate(var(--rtlty-tilt-char)); }
  .rtlty .x-risu-rtlty-pair-user { transform: rotate(var(--rtlty-tilt-user)); }
}
.rtlty__side-name {
  font-family: var(--rtlty-font-display);
  font-size: 1.2em;
  font-weight: 400;
  padding: 0 .6em;
  border-radius: .2rem;
  border: 1px solid var(--rtlty-line);
  background: var(--rtlty-paper);
  color: var(--rtlty-strong, var(--rtlty-ink));
  box-shadow: 0 2px 6px var(--rtlty-shadow);
}
.rtlty__main {
  padding: 1.3rem clamp(1.05rem, 3.2vw, 1.9rem) .95rem;
  border: 1px solid var(--rtlty-line);
  border-radius: .35rem;
  box-shadow: 0 2px 6px var(--rtlty-shadow), 0 12px 28px var(--rtlty-shadow);
}
.rtlty .rtlty__bg {
  background-image:
    var(--rtlty-bg-sheen),
    repeating-linear-gradient(to bottom, transparent 0, transparent calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height)));
  background-color: var(--rtlty-paper);
  background-position: 0 0, 0 1.3rem;
}
.rtlty--user .rtlty__bg { background-color: var(--rtlty-paper-user); }
.rtlty__speaker {
  padding-bottom: .4rem;
  border-bottom: 1px solid var(--rtlty-line);
  font-family: var(--rtlty-font-display);
  font-size: 1.15em;
  font-weight: 400;
}
.rtlty__footer { margin-top: .75rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlty__content :where(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlty-font-body); font-family: var(--rtlty-font-body); }
@media (max-width: 1039px) {
  .rtlty__frame { padding: 4px; }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user { border-width: 4px; }
}

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (남색 편지지) ── */
.rtlty {
  --rtlty-paper: #1e263f;
  --rtlty-paper-user: #242d48;
  --rtlty-rule: rgba(180, 192, 224, .1);
  --rtlty-ink: #e5e0d4;
  --rtlty-strong: #f6f2e8;
  --rtlty-muted: #a3a8ba;
  --rtlty-accent: #cbb17a;
  --rtlty-dialog: #ebd49c;
  --rtlty-stamp: #ece7d8;
  --rtlty-shadow: rgba(0, 0, 0, .36);
  --rtlty-line: #343f5f;
  --rtlty-tint: #2a3350;
  --rtlty-edit-bg: #1a2137;
}

@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlty-font-size로 바꿉니다. */
.rtlty {
  --rtlty-bg-fill: transparent;
  --rtlty-bg-border: 0;
  --rtlty-blur: none;
  --rtlty-bg-edge: none;
  --rtlty-bg-sheen: linear-gradient(transparent, transparent);
  --rtlty-bg-fallback: transparent;
  --rtlty-font-body: "Gowun Batang", "Noto Serif KR", serif;
  --rtlty-font-display: "Nanum Pen Script", "Gowun Batang", cursive;
  --rtlty-font-size: 16px;
  --rtlty-line-height: 1.9;
  --rtlty-para-gap: 0;
  --rtlty-dialog-weight: 700;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtlty {
  --risu-font-family: var(--rtlty-font-body);
  --FontColorStandard: var(--rtlty-ink);
  --FontColorBold: var(--rtlty-strong, var(--rtlty-ink));
  --FontColorItalic: var(--rtlty-muted);
  --FontColorItalicBold: var(--rtlty-muted);
  --FontColorQuote1: var(--rtlty-muted);
  --FontColorQuote2: var(--rtlty-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-body);
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
  letter-spacing: var(--rtlty-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtlty, .rtlty *, .rtlty *::before, .rtlty *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtlty.rtlty { display: block; }
.rtlty ::selection { background: color-mix(in srgb, var(--rtlty-accent) 26%, transparent); color: inherit; }
.rtlty__content {
  min-width: 0;
  color: var(--rtlty-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtlty__content .chattext {
  --tw-prose-code: var(--rtlty-strong, var(--rtlty-ink));
  --tw-prose-pre-code: var(--rtlty-ink);
  --tw-prose-pre-bg: var(--rtlty-tint);
  max-width: none;
  color: var(--rtlty-ink);
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtlty__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty__content :where(p) { margin: 0 0 var(--rtlty-para-gap); }
.rtlty__content :where(p:last-child) { margin-bottom: 0; }
.rtlty__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtlty-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtlty-strong, var(--rtlty-ink));
  font-family: var(--rtlty-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtlty__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtlty__content :where(h1) { font-size: calc(var(--rtlty-font-size) * 1.55); }
.rtlty__content :where(h2) { font-size: calc(var(--rtlty-font-size) * 1.32); }
.rtlty__content :where(h3) { font-size: calc(var(--rtlty-font-size) * 1.15); }
.rtlty__content :where(h4, h5, h6) { font-size: var(--rtlty-font-size); color: var(--rtlty-muted); }
.rtlty__content :where(strong) { font-weight: 700; color: var(--rtlty-strong, var(--rtlty-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtlty__content :where(em) { font-style: normal; color: var(--rtlty-muted); }
.rtlty__content mark[risu-mark="quote1"],
.rtlty__content mark[risu-mark="blockquote1"] { color: var(--rtlty-muted); background: transparent; }
.rtlty__content mark[risu-mark="quote2"],
.rtlty__content mark[risu-mark="blockquote2"] {
  color: var(--rtlty-dialog);
  font-weight: var(--rtlty-dialog-weight);
  background: transparent;
}
.rtlty__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtlty-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtlty-tint);
  color: var(--rtlty-muted);
}
.rtlty__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtlty__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtlty-ink); }
.rtlty__content :where(li)::marker { color: var(--rtlty-accent); }
.rtlty__content :where(a) {
  color: var(--rtlty-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtlty-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtlty__content :where(a:hover) { text-decoration-color: currentColor; }
.rtlty__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtlty-line) 15%, var(--rtlty-line) 85%, transparent);
}
.rtlty__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtlty-strong, var(--rtlty-ink));
  background: var(--rtlty-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.5;
}
.rtlty__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  border: 1px solid var(--rtlty-line);
  border-radius: .5rem;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.55;
}
.rtlty__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtlty__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtlty__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtlty-ink);
  border-bottom: 1px solid var(--rtlty-line);
  text-align: left;
  vertical-align: top;
}
.rtlty__content :where(th) {
  background: var(--rtlty-tint);
  color: var(--rtlty-strong, var(--rtlty-ink));
  font-weight: 600;
}
.rtlty__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtlty__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtlty-ink) !important;
  background: var(--rtlty-edit-bg) !important;
  border: 1px solid var(--rtlty-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtlty__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtlty-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtlty-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtlty__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtlty-muted);
  --color-textcolor2: var(--rtlty-muted);
  --color-textcolor: var(--rtlty-ink);
  --color-darkborderc: var(--rtlty-line);
  --color-darkbutton: var(--rtlty-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtlty-muted);
}
.rtlty__info, .rtlty__actions { min-width: 0; max-width: 100%; }
.rtlty__info > div, .rtlty__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtlty-muted); }
.rtlty__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtlty__info button.transition-all,
.rtlty__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtlty__info button.transition-all:hover,
.rtlty__actions button[class*="button-icon-"]:hover { background: var(--rtlty-tint); color: var(--rtlty-ink); }
.rtlty__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtlty-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtlty__info button:not(.transition-all):hover { background: var(--rtlty-tint); color: var(--rtlty-ink); }
.rtlty :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtlty-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlty__portrait { overflow: hidden; background: var(--rtlty-tint); }
.rtlty__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtlty, .rtlty * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtlty .rtlty__bg {
    background: var(--rtlty-bg-fallback, var(--rtlty-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtlty .rtlty__bg { background: var(--rtlty-bg-fallback, var(--rtlty-bg-fill)); }
}

.rtlty__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlty-bg-fill);
  border: var(--rtlty-bg-border, 0);
  -webkit-backdrop-filter: var(--rtlty-blur);
  backdrop-filter: var(--rtlty-blur);
  box-shadow: var(--rtlty-bg-edge);
}

/* 구조: 편지 양쪽 */


.rtlty {
  --rtlty-col: 44rem;
  --rtlty-gap: clamp(1rem, 2.2vw, 1.8rem);
  --rtlty-edge: 1rem;
  --rtlty-fixed-bottom: 5rem;
  --rtlty-fixed-w: max(8rem, min(calc((100% - var(--rtlty-col)) / 2 - var(--rtlty-gap) - var(--rtlty-edge)), calc((100vh - var(--rtlty-edge) - var(--rtlty-fixed-bottom)) * 3 / 4)));
  --rtlty-pad: .65rem;
  max-width: var(--rtlty-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtlty__side { display: none; }
.rtlty__main { position: relative; min-width: 0; }
.rtlty__speaker {
  display: flex;
  align-items: center;
  gap: .45rem;
  margin-bottom: .55rem;
  color: var(--rtlty-muted);
  font-size: .82em;
  font-weight: 700;
  letter-spacing: .02em;
}
.rtlty--char .rtlty__speaker { color: var(--rtlty-strong, var(--rtlty-ink)); }
.rtlty .x-risu-rtlty-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
.rtlty .x-risu-rtlty-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtlty) { transform: translateZ(0); }

/* PC: 1040px 이상에서만 양옆 고정 초상을 띄우고 가운데 열과 겹치지 않게 폭을 확보합니다. */
@media (min-width: 1040px) {
  .rtlty { --rtlty-col: min(44rem, calc(100% - 22rem)); }
  .chat-message-container:first-child .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    margin-block: auto;
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-char,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-pair-char {
    left: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-char));
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-user,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-pair-user {
    right: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-user));
  }
  .chat-message-container:first-child .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--char .x-risu-rtlty-pair-char,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child .rtlty--user .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--user .x-risu-rtlty-pair-user,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty--user .x-risu-rtlty-pair-user {
    translate: 0 -4px;
    scale: 1.018;
    filter: drop-shadow(0 16px 14px rgba(0, 0, 0, .24));
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
  .flex-col-reverse:not(:has(> .chat-message-container:nth-child(-n+2) .x-risu-rtlty-pair)) + .risu-chat .rtlty .x-risu-rtlty-fade {
    /* 왼쪽 초상과 똑같은 칸을 투명하게 겹쳐 두고 그 왼쪽 위 모서리에 단추를 놓습니다.
       앵커 위치 지정이 없는 브라우저(Firefox, 이전 Safari)에서도 단추가 초상에서 떨어지지 않습니다. */
    display: block;
    position: fixed;
    z-index: 2;
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    left: var(--rtlty-edge);
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    margin: auto 0;
    padding: .6rem;
    pointer-events: none;
  }
  .rtlty .x-risu-rtlty-fade > summary {
    pointer-events: auto;
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .34);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .28);
    opacity: .72;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtlty .x-risu-rtlty-fade > summary::-webkit-details-marker { display: none; }
  .rtlty .x-risu-rtlty-fade > summary::before { content: "◐"; }
  .rtlty .x-risu-rtlty-fade > summary:hover,
  .rtlty .x-risu-rtlty-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .54); }
  .rtlty.rtlty .x-risu-rtlty-pair.x-risu-rtlty-pair:has(> .x-risu-rtlty-fade[open]) :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰·좁은 창: 메시지마다 위에 두 초상이 마주 보고, 반대편 초상이 빈 액자 위에 정확히 겹칩니다. */
@media (max-width: 1039px) {
  .rtlty.rtlty { display: grid; }
  .rtlty {
    --rtlty-side-w: clamp(4.6rem, 16vw, 6rem);
    --rtlty-row-gap: .85rem;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    row-gap: var(--rtlty-row-gap);
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtlty-pad) 0;
  }
  .rtlty__side { display: flex; flex-direction: row; align-items: center; gap: .55rem; min-width: 0; }
  .rtlty__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtlty__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtlty__frame { position: relative; width: var(--rtlty-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtlty__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtlty__side-name { min-width: 0; color: var(--rtlty-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtlty__main { grid-column: 1 / -1; grid-row: 2; min-width: 0; max-width: 100%; }
  .rtlty__speaker { display: none; }
  .rtlty--char .rtlty__side--char .rtlty__side-name, .rtlty--user .rtlty__side--user .rtlty__side-name { color: var(--rtlty-strong, var(--rtlty-ink)); }
  .rtlty--char .rtlty__side--char .rtlty__frame, .rtlty--user .rtlty__side--user .rtlty__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 8px rgba(0, 0, 0, .22));
  }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
    position: absolute;
    z-index: 2;
    bottom: calc(100% + var(--rtlty-row-gap) + 1px);
    width: var(--rtlty-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtlty--user .x-risu-rtlty-pair-char { display: block; left: 0; }
  .rtlty--char .x-risu-rtlty-pair-user { display: block; right: 0; }
}
/* 우표 액자: 어떤 배경 위에서도 깔끔한 톱니 우표 테두리 */
.rtlty__frame {
  padding: 6px;
  background: var(--rtlty-stamp);
  border: 1px solid var(--rtlty-line);
  border-radius: 3px;
  outline: 1px dashed color-mix(in srgb, var(--rtlty-muted) 42%, transparent);
  outline-offset: -3px;
  box-shadow: 0 5px 14px var(--rtlty-shadow);
  transform: rotate(var(--rtlty-tilt-char));
}
.rtlty__side--user .rtlty__frame { transform: rotate(var(--rtlty-tilt-user)); }
.rtlty { --rtlty-tilt-char: -1.6deg; --rtlty-tilt-user: 1.6deg; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  border: 6px solid var(--rtlty-stamp);
  border-radius: 3px;
  background-clip: padding-box;
  outline: 1px dashed color-mix(in srgb, var(--rtlty-muted) 42%, transparent);
  outline-offset: -3px;
  box-shadow: 0 10px 24px var(--rtlty-shadow);
}
@media (max-width: 1039px) {
  .rtlty .x-risu-rtlty-pair-char { transform: rotate(var(--rtlty-tilt-char)); }
  .rtlty .x-risu-rtlty-pair-user { transform: rotate(var(--rtlty-tilt-user)); }
}
.rtlty__side-name {
  font-family: var(--rtlty-font-display);
  font-size: 1.2em;
  font-weight: 400;
  padding: 0 .6em;
  border-radius: .2rem;
  border: 1px solid var(--rtlty-line);
  background: var(--rtlty-paper);
  color: var(--rtlty-strong, var(--rtlty-ink));
  box-shadow: 0 2px 6px var(--rtlty-shadow);
}
.rtlty__main {
  padding: 1.3rem clamp(1.05rem, 3.2vw, 1.9rem) .95rem;
  border: 1px solid var(--rtlty-line);
  border-radius: .35rem;
  box-shadow: 0 2px 6px var(--rtlty-shadow), 0 12px 28px var(--rtlty-shadow);
}
.rtlty .rtlty__bg {
  background-image:
    var(--rtlty-bg-sheen),
    repeating-linear-gradient(to bottom, transparent 0, transparent calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height)));
  background-color: var(--rtlty-paper);
  background-position: 0 0, 0 1.3rem;
}
.rtlty--user .rtlty__bg { background-color: var(--rtlty-paper-user); }
.rtlty__speaker {
  padding-bottom: .4rem;
  border-bottom: 1px solid var(--rtlty-line);
  font-family: var(--rtlty-font-display);
  font-size: 1.15em;
  font-weight: 400;
}
.rtlty__footer { margin-top: .75rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlty__content :where(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlty-font-body); font-family: var(--rtlty-font-body); }
@media (max-width: 1039px) {
  .rtlty__frame { padding: 4px; }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user { border-width: 4px; }
}

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (글래스) ── */
.rtlty {
  --rtlty-blur: blur(16px) saturate(1.3);
  --rtlty-bg-sheen: radial-gradient(120% 80% at 0% 0%, rgba(255, 255, 255, .13), transparent 54%), linear-gradient(165deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015) 68%);
  --rtlty-bg-edge: 0 14px 36px -14px rgba(0, 0, 0, .52), inset 0 1px 0 rgba(255, 255, 255, .24), inset 0 0 0 1px rgba(255, 255, 255, .13);
  --rtlty-bg-fallback: rgba(16, 18, 26, .88);
  --rtlty-paper: rgba(16, 17, 23, .42);
  --rtlty-paper-user: rgba(28, 30, 38, .44);
  --rtlty-rule: rgba(255, 255, 255, .07);
  --rtlty-ink: #eeece5;
  --rtlty-strong: #ffffff;
  --rtlty-muted: rgba(230, 228, 222, .68);
  --rtlty-accent: #e2cca4;
  --rtlty-dialog: #ffffff;
  --rtlty-stamp: rgba(250, 246, 238, .9);
  --rtlty-shadow: rgba(0, 0, 0, .28);
  --rtlty-line: rgba(255, 255, 255, .15);
  --rtlty-tint: rgba(255, 255, 255, .08);
  --rtlty-edit-bg: rgba(10, 11, 16, .52);
}

@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: .9rem .75rem;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlta-font-size로 바꿉니다. */
.rtlta {
  --rtlta-bg-fill: transparent;
  --rtlta-bg-border: 0;
  --rtlta-blur: none;
  --rtlta-bg-edge: none;
