  --color-textcolor2: var(--rtfan-muted);
  --color-textcolor: var(--rtfan-ink);
  --color-darkborderc: var(--rtfan-line);
  --color-darkbutton: var(--rtfan-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtfan-muted);
}
.rtfan__info, .rtfan__actions { min-width: 0; max-width: 100%; }
.rtfan__info > div, .rtfan__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtfan-muted); }
.rtfan__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtfan__info button.transition-all,
.rtfan__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtfan__info button.transition-all:hover,
.rtfan__actions button[class*="button-icon-"]:hover { background: var(--rtfan-tint); color: var(--rtfan-ink); }
.rtfan__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtfan-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtfan__info button:not(.transition-all):hover { background: var(--rtfan-tint); color: var(--rtfan-ink); }
.rtfan :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtfan-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtfan__portrait { overflow: hidden; background: var(--rtfan-tint); }
.rtfan__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtfan, .rtfan * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtfan .rtfan__bg {
    background: var(--rtfan-bg-fallback, var(--rtfan-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtfan .rtfan__bg { background: var(--rtfan-bg-fallback, var(--rtfan-bg-fill)); }
}

.rtfan__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtfan-bg-fill);
  border: var(--rtfan-bg-border, 0);
  -webkit-backdrop-filter: var(--rtfan-blur);
  backdrop-filter: var(--rtfan-blur);
  box-shadow: var(--rtfan-bg-edge);
}

/* 구조: 판타지 */

.rtfan {
  max-width: 50rem;
  margin: 0 auto;
  padding: clamp(1.5rem, 4%, 2.4rem) clamp(1.4rem, 5%, 2.9rem) 1.3rem;
  border-radius: .45rem;
  border: 1px solid var(--rtfan-line);
  box-shadow: 0 12px 32px var(--rtfan-shadow);
}
/* 양피지 연대기 바탕: 얼룩, 모서리 음영, 이중 세선 테두리 */
.rtfan .rtfan__bg {
  background:
    var(--rtfan-bg-sheen),
    radial-gradient(ellipse at 10% 6%, var(--rtfan-stain) 0, transparent 44%),
    radial-gradient(ellipse at 92% 94%, var(--rtfan-stain) 0, transparent 42%),
    radial-gradient(ellipse at 50% 50%, transparent 56%, var(--rtfan-vignette, transparent) 100%),
    var(--rtfan-paper);
  box-shadow:
    var(--rtfan-bg-edge),
    inset 0 0 0 1px var(--rtfan-line),
    inset 0 0 0 5px transparent,
    inset 0 0 0 6px color-mix(in srgb, var(--rtfan-accent) 32%, transparent);
}
.rtfan::before, .rtfan::after {
  content: "✦";
  position: absolute;
  top: .62rem;
  color: var(--rtfan-accent);
  font-size: clamp(.72rem, 1.4vw, 1rem);
  line-height: 1;
  opacity: .78;
  pointer-events: none;
}
.rtfan::before { left: .72rem; }
.rtfan::after { right: .72rem; }
