  display: flex;
  align-items: center;
  gap: .95rem;
  margin-bottom: 1.05rem;
  padding-bottom: .75rem;
  border-bottom: 1px solid var(--rtfan-line);
}
/* 입체 밀랍 인장 */
.rtfan__portrait {
  flex: 0 0 auto;
  width: var(--rtfan-seal-w);
  aspect-ratio: 1;
  border-radius: 50%;
  border: clamp(2px, .5vw, 4px) solid var(--rtfan-seal);
  box-shadow:
    inset 0 2px 4px rgba(255, 255, 255, .25),
    0 0 0 clamp(2px, .45vw, 3.5px) var(--rtfan-seal-dark),
    0 5px 14px var(--rtfan-shadow);
}
