.rtsf__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtsf-bg-fill);
  border: var(--rtsf-bg-border, 0);
  -webkit-backdrop-filter: var(--rtsf-blur);
  backdrop-filter: var(--rtsf-blur);
  box-shadow: var(--rtsf-bg-edge);
}

/* 구조: SF */

/* 화면 테두리(베젤): 바탕 층(__bg)에 베젤 색과 유리 흐림을 두어 글래스에서도 한 겹만 반투명해집니다. */
.rtsf {
  max-width: 54rem;
  margin: 0 auto;
  padding: clamp(5px, 1.2%, 10px);
  border-radius: clamp(.5rem, 1.6%, 1rem);
  box-shadow: 0 0 0 1px var(--rtsf-frame), 0 10px 26px rgba(0, 0, 0, .32);
}
.rtsf .rtsf__bg { background: var(--rtsf-bg-sheen), var(--rtsf-bezel); }
.rtsf__screen {
  position: relative;
  padding: 1rem clamp(1rem, 3vw, 1.65rem) .85rem;
  background:
    repeating-linear-gradient(to bottom, var(--rtsf-scan) 0, var(--rtsf-scan) 1px, transparent 1px, transparent 3px),
    var(--rtsf-panel);
  border-radius: clamp(.35rem, 1%, .65rem);
  box-shadow: inset 0 0 34px var(--rtsf-inner-glow), inset 0 0 0 1px var(--rtsf-frame);
}
.rtsf__screen::before, .rtsf__screen::after {
  content: "";
  position: absolute;
  width: clamp(10px, 2.8%, 20px);
  aspect-ratio: 1;
  border: 2px solid var(--rtsf-accent);
  opacity: .85;
  pointer-events: none;
}
.rtsf__screen::before { top: 6px; left: 6px; border-right: 0; border-bottom: 0; }
.rtsf__screen::after { bottom: 6px; right: 6px; border-left: 0; border-top: 0; }
.rtsf__bar {
  display: flex;
  align-items: center;
  gap: .55rem;
  margin-bottom: .85rem;
  padding-bottom: .55rem;
  border-bottom: 1px solid var(--rtsf-frame);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: .72em;
  letter-spacing: .12em;
  color: var(--rtsf-muted);
}
.rtsf__channel {
  display: inline-flex;
  align-items: center;
  gap: .38em;
  padding: .14em .52em;
  border-radius: .22rem;
  background: color-mix(in srgb, var(--rtsf-accent) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--rtsf-accent) 36%, transparent);
  color: var(--rtsf-accent);
  font-weight: 600;
}
.rtsf__channel::before {
  content: "";
  width: .42em;
  height: .42em;
  border-radius: 50%;
  background: var(--rtsf-accent);
  box-shadow: 0 0 6px var(--rtsf-accent);
}
.rtsf__name { color: var(--rtsf-strong, var(--rtsf-ink)); letter-spacing: .06em; font-weight: 600; }
.rtsf__signal {
  margin-left: auto;
  width: 2.2em;
  height: .55em;
  background: repeating-linear-gradient(to right, var(--rtsf-accent) 0 3px, transparent 3px 5px);
  opacity: .8;
}
.rtsf__body { display: flex; align-items: flex-start; gap: 1rem; }
.rtsf__portrait {
  position: relative;
  flex: 0 0 auto;
  width: var(--rtsf-portrait-w);
  aspect-ratio: 4 / 5;
  border-radius: .25rem;
  border: 1px solid var(--rtsf-accent);
  box-shadow: 0 0 14px var(--rtsf-inner-glow);
}
.rtsf__portrait::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(to bottom, transparent 0 2px, var(--rtsf-scan-strong) 2px 3px);
  pointer-events: none;
}
.rtsf { --rtsf-portrait-w: clamp(3.6rem, 11%, 6rem); }
.rtsf--user { --rtsf-portrait-w: clamp(2.6rem, 7%, 3.6rem); }
.rtsf--user .rtsf__body { flex-direction: row-reverse; }
.rtsf__content { flex: 1 1 auto; }
.rtsf__content :where(h1, h2, h3) { color: var(--rtsf-accent); }
.rtsf__footer { margin-top: .85rem; padding-top: .5rem; border-top: 1px solid var(--rtsf-frame); font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace; font-size: .78em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (글래스) ── */
.rtsf {
  --rtsf-blur: blur(16px) saturate(1.3);
  --rtsf-bg-sheen: radial-gradient(120% 80% at 0% 0%, rgba(255, 255, 255, .13), transparent 54%), linear-gradient(165deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015) 68%);
  --rtsf-bg-edge: 0 14px 36px -14px rgba(0, 0, 0, .52), inset 0 1px 0 rgba(255, 255, 255, .24), inset 0 0 0 1px rgba(255, 255, 255, .13);
  --rtsf-bg-fallback: rgba(16, 18, 26, .88);
  --rtsf-bezel: rgba(10, 15, 20, .38);
  --rtsf-panel: rgba(255, 255, 255, .025);
  --rtsf-frame: rgba(255, 255, 255, .16);
  --rtsf-scan: rgba(255, 255, 255, .022);
  --rtsf-scan-strong: rgba(0, 0, 0, .14);
  --rtsf-inner-glow: rgba(180, 224, 224, .08);
  --rtsf-ink: #eaf0f2;
  --rtsf-strong: #ffffff;
  --rtsf-muted: rgba(225, 232, 236, .68);
  --rtsf-accent: #bed9d6;
  --rtsf-dialog: #ffffff;
  --rtsf-line: rgba(255, 255, 255, .14);
  --rtsf-tint: rgba(255, 255, 255, .08);
  --rtsf-edit-bg: rgba(10, 13, 18, .52);
}

@import url("https://fonts.googleapis.com/css2?family=Special+Elite&family=Nanum+Myeongjo:wght@400;700&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 1.2rem .75rem .6rem;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtnoir-font-size로 바꿉니다. */
.rtnoir {
  --rtnoir-bg-fill: transparent;
  --rtnoir-bg-border: 0;
  --rtnoir-blur: none;
  --rtnoir-bg-edge: none;
  --rtnoir-bg-sheen: linear-gradient(transparent, transparent);
  --rtnoir-bg-fallback: transparent;
  --rtnoir-font-body: "Nanum Myeongjo", "Noto Serif KR", serif;
  --rtnoir-font-display: "Special Elite", "Courier New", ui-monospace, monospace;
  --rtnoir-font-size: 16px;
  --rtnoir-line-height: 1.85;
  --rtnoir-para-gap: .85em;
  --rtnoir-dialog-weight: 700;
  --rtnoir-stamp: "CONFIDENTIAL";
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtnoir {
  --risu-font-family: var(--rtnoir-font-body);
  --FontColorStandard: var(--rtnoir-ink);
  --FontColorBold: var(--rtnoir-strong, var(--rtnoir-ink));
  --FontColorItalic: var(--rtnoir-muted);
  --FontColorItalicBold: var(--rtnoir-muted);
  --FontColorQuote1: var(--rtnoir-muted);
  --FontColorQuote2: var(--rtnoir-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtnoir-ink);
  font-family: var(--rtnoir-font-body);
  font-size: var(--rtnoir-font-size);
  line-height: var(--rtnoir-line-height);
  letter-spacing: var(--rtnoir-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtnoir, .rtnoir *, .rtnoir *::before, .rtnoir *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtnoir.rtnoir { display: block; }
.rtnoir ::selection { background: color-mix(in srgb, var(--rtnoir-accent) 26%, transparent); color: inherit; }
.rtnoir__content {
  min-width: 0;
  color: var(--rtnoir-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtnoir__content .chattext {
  --tw-prose-code: var(--rtnoir-strong, var(--rtnoir-ink));
  --tw-prose-pre-code: var(--rtnoir-ink);
  --tw-prose-pre-bg: var(--rtnoir-tint);
  max-width: none;
  color: var(--rtnoir-ink);
  font-size: var(--rtnoir-font-size) !important;
  line-height: var(--rtnoir-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtnoir__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtnoir-font-size);
  line-height: var(--rtnoir-line-height);
}
.rtnoir__content :where(p) { margin: 0 0 var(--rtnoir-para-gap); }
.rtnoir__content :where(p:last-child) { margin-bottom: 0; }
.rtnoir__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtnoir-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtnoir-strong, var(--rtnoir-ink));
  font-family: var(--rtnoir-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtnoir__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtnoir__content :where(h1) { font-size: calc(var(--rtnoir-font-size) * 1.55); }
.rtnoir__content :where(h2) { font-size: calc(var(--rtnoir-font-size) * 1.32); }
.rtnoir__content :where(h3) { font-size: calc(var(--rtnoir-font-size) * 1.15); }
.rtnoir__content :where(h4, h5, h6) { font-size: var(--rtnoir-font-size); color: var(--rtnoir-muted); }
.rtnoir__content :where(strong) { font-weight: 700; color: var(--rtnoir-strong, var(--rtnoir-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtnoir__content :where(em) { font-style: normal; color: var(--rtnoir-muted); }
.rtnoir__content mark[risu-mark="quote1"],
.rtnoir__content mark[risu-mark="blockquote1"] { color: var(--rtnoir-muted); background: transparent; }
.rtnoir__content mark[risu-mark="quote2"],
.rtnoir__content mark[risu-mark="blockquote2"] {
  color: var(--rtnoir-dialog);
  font-weight: var(--rtnoir-dialog-weight);
  background: transparent;
}
.rtnoir__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtnoir-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtnoir-tint);
  color: var(--rtnoir-muted);
}
.rtnoir__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtnoir__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtnoir-ink); }
.rtnoir__content :where(li)::marker { color: var(--rtnoir-accent); }
.rtnoir__content :where(a) {
  color: var(--rtnoir-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtnoir-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtnoir__content :where(a:hover) { text-decoration-color: currentColor; }
.rtnoir__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtnoir-line) 15%, var(--rtnoir-line) 85%, transparent);
}
.rtnoir__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtnoir-strong, var(--rtnoir-ink));
  background: var(--rtnoir-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtnoir-font-size) * .88);
  line-height: 1.5;
}
.rtnoir__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtnoir-ink);
  background: var(--rtnoir-tint);
  border: 1px solid var(--rtnoir-line);
  border-radius: .5rem;
  font-size: calc(var(--rtnoir-font-size) * .88);
  line-height: 1.55;
}
.rtnoir__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtnoir__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtnoir__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtnoir-ink);
  border-bottom: 1px solid var(--rtnoir-line);
  text-align: left;
  vertical-align: top;
}
.rtnoir__content :where(th) {
  background: var(--rtnoir-tint);
  color: var(--rtnoir-strong, var(--rtnoir-ink));
  font-weight: 600;
}
.rtnoir__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtnoir__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtnoir-ink) !important;
  background: var(--rtnoir-edit-bg) !important;
  border: 1px solid var(--rtnoir-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtnoir-font-size) !important;
  line-height: var(--rtnoir-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtnoir__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtnoir-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtnoir-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtnoir__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtnoir-muted);
  --color-textcolor2: var(--rtnoir-muted);
  --color-textcolor: var(--rtnoir-ink);
  --color-darkborderc: var(--rtnoir-line);
  --color-darkbutton: var(--rtnoir-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtnoir-muted);
}
.rtnoir__info, .rtnoir__actions { min-width: 0; max-width: 100%; }
.rtnoir__info > div, .rtnoir__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtnoir-muted); }
.rtnoir__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtnoir__info button.transition-all,
.rtnoir__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtnoir__info button.transition-all:hover,
.rtnoir__actions button[class*="button-icon-"]:hover { background: var(--rtnoir-tint); color: var(--rtnoir-ink); }
.rtnoir__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtnoir-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtnoir__info button:not(.transition-all):hover { background: var(--rtnoir-tint); color: var(--rtnoir-ink); }
.rtnoir :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtnoir-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtnoir__portrait { overflow: hidden; background: var(--rtnoir-tint); }
.rtnoir__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtnoir, .rtnoir * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtnoir .rtnoir__bg {
    background: var(--rtnoir-bg-fallback, var(--rtnoir-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtnoir .rtnoir__bg { background: var(--rtnoir-bg-fallback, var(--rtnoir-bg-fill)); }
}

.rtnoir__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtnoir-bg-fill);
  border: var(--rtnoir-bg-border, 0);
  -webkit-backdrop-filter: var(--rtnoir-blur);
  backdrop-filter: var(--rtnoir-blur);
  box-shadow: var(--rtnoir-bg-edge);
}

/* 구조: 현대 느와르 */

.rtnoir { max-width: 52rem; margin: 0 auto; padding-top: 1.75rem; }
.rtnoir__tab {
  position: absolute;
  top: 0;
  left: clamp(.8rem, 3%, 1.6rem);
  max-width: calc(100% - 9rem);
  padding: .34rem 1.65rem .28rem;
  background: var(--rtnoir-folder);
  clip-path: polygon(7% 0, 93% 0, 100% 100%, 0 100%);
  color: var(--rtnoir-folder-ink);
  font-family: var(--rtnoir-font-display);
  font-size: .78em;
  letter-spacing: .12em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rtnoir__sheet {
  position: relative;
  padding: 1.45rem clamp(1.05rem, 4vw, 2.1rem) 1.05rem;
  border: 1px solid var(--rtnoir-line);
  border-top: 6px solid var(--rtnoir-folder);
  border-radius: 0 .35rem .35rem .35rem;
  box-shadow: 0 8px 22px var(--rtnoir-shadow);
}
.rtnoir .rtnoir__bg { background: var(--rtnoir-bg-sheen), var(--rtnoir-paper); }
.rtnoir__sheet::after {
  content: var(--rtnoir-stamp);
  position: absolute;
  top: -1.6rem;
  right: clamp(.65rem, 3%, 1.25rem);
  padding: .08rem .52rem;
  border: 2px solid var(--rtnoir-accent);
  outline: 1px solid color-mix(in srgb, var(--rtnoir-accent) 55%, transparent);
  outline-offset: 2px;
  border-radius: .2rem;
  color: var(--rtnoir-accent);
  font-family: var(--rtnoir-font-display);
  font-size: clamp(.56rem, 1.3vw, .76rem);
  letter-spacing: .2em;
  opacity: .72;
  transform: rotate(-4deg);
  pointer-events: none;
}
/* 이중 금속 클립으로 고정한 증명사진 */
.rtnoir__photo {
  position: relative;
  float: right;
  width: calc(var(--rtnoir-portrait-w) + .85rem);
  margin: .3rem 0 .85rem 1.25rem;
  padding: .42rem .42rem .34rem;
  background: var(--rtnoir-photo);
  border-radius: 2px;
  box-shadow: 0 4px 12px var(--rtnoir-shadow);
  transform: rotate(2deg);
}
.rtnoir__photo::before, .rtnoir__photo::after {
  content: "";
  position: absolute;
  top: -.65rem;
  left: 22%;
  width: clamp(.72rem, 22%, 1.1rem);
  height: clamp(1.55rem, 48%, 2.3rem);
  border: 2px solid var(--rtnoir-clip);
  border-radius: 999px;
  transform: rotate(-6deg);
  pointer-events: none;
}
.rtnoir__photo::after {
  top: -.45rem;
  left: calc(22% + 3px);
  width: clamp(.42rem, 13%, .66rem);
  height: clamp(1.1rem, 34%, 1.65rem);
  opacity: .75;
}
.rtnoir__portrait { width: 100%; aspect-ratio: 3 / 4; filter: var(--rtnoir-photo-filter); }
.rtnoir__caption {
  margin-top: .28rem;
  color: var(--rtnoir-photo-ink);
  font-family: var(--rtnoir-font-display);
