  letter-spacing: var(--rtori-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtori, .rtori *, .rtori *::before, .rtori *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtori.rtori { display: block; }
.rtori ::selection { background: color-mix(in srgb, var(--rtori-accent) 26%, transparent); color: inherit; }
.rtori__content {
  min-width: 0;
  color: var(--rtori-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtori__content .chattext {
  --tw-prose-code: var(--rtori-strong, var(--rtori-ink));
  --tw-prose-pre-code: var(--rtori-ink);
  --tw-prose-pre-bg: var(--rtori-tint);
  max-width: none;
  color: var(--rtori-ink);
  font-size: var(--rtori-font-size) !important;
  line-height: var(--rtori-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtori__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtori-font-size);
  line-height: var(--rtori-line-height);
}
.rtori__content :where(p) { margin: 0 0 var(--rtori-para-gap); }
.rtori__content :where(p:last-child) { margin-bottom: 0; }
.rtori__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtori-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtori-strong, var(--rtori-ink));
  font-family: var(--rtori-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtori__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtori__content :where(h1) { font-size: calc(var(--rtori-font-size) * 1.55); }
.rtori__content :where(h2) { font-size: calc(var(--rtori-font-size) * 1.32); }
.rtori__content :where(h3) { font-size: calc(var(--rtori-font-size) * 1.15); }
.rtori__content :where(h4, h5, h6) { font-size: var(--rtori-font-size); color: var(--rtori-muted); }
.rtori__content :where(strong) { font-weight: 700; color: var(--rtori-strong, var(--rtori-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtori__content :where(em) { font-style: normal; color: var(--rtori-muted); }
.rtori__content mark[risu-mark="quote1"],
.rtori__content mark[risu-mark="blockquote1"] { color: var(--rtori-muted); background: transparent; }
.rtori__content mark[risu-mark="quote2"],
.rtori__content mark[risu-mark="blockquote2"] {
  color: var(--rtori-dialog);
  font-weight: var(--rtori-dialog-weight);
  background: transparent;
}
.rtori__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtori-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtori-tint);
  color: var(--rtori-muted);
}
.rtori__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtori__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtori-ink); }
.rtori__content :where(li)::marker { color: var(--rtori-accent); }
.rtori__content :where(a) {
  color: var(--rtori-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtori-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtori__content :where(a:hover) { text-decoration-color: currentColor; }
.rtori__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtori-line) 15%, var(--rtori-line) 85%, transparent);
}
.rtori__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtori-strong, var(--rtori-ink));
  background: var(--rtori-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtori-font-size) * .88);
  line-height: 1.5;
}
.rtori__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtori-ink);
  background: var(--rtori-tint);
  border: 1px solid var(--rtori-line);
  border-radius: .5rem;
  font-size: calc(var(--rtori-font-size) * .88);
  line-height: 1.55;
}
.rtori__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtori__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtori__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtori-ink);
  border-bottom: 1px solid var(--rtori-line);
  text-align: left;
  vertical-align: top;
}
.rtori__content :where(th) {
  background: var(--rtori-tint);
  color: var(--rtori-strong, var(--rtori-ink));
  font-weight: 600;
}
.rtori__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtori__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtori-ink) !important;
  background: var(--rtori-edit-bg) !important;
  border: 1px solid var(--rtori-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtori-font-size) !important;
  line-height: var(--rtori-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtori__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtori-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtori-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtori__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtori-muted);
  --color-textcolor2: var(--rtori-muted);
  --color-textcolor: var(--rtori-ink);
  --color-darkborderc: var(--rtori-line);
  --color-darkbutton: var(--rtori-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtori-muted);
}
.rtori__info, .rtori__actions { min-width: 0; max-width: 100%; }
.rtori__info > div, .rtori__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtori-muted); }
.rtori__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtori__info button.transition-all,
.rtori__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtori__info button.transition-all:hover,
.rtori__actions button[class*="button-icon-"]:hover { background: var(--rtori-tint); color: var(--rtori-ink); }
.rtori__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtori-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtori__info button:not(.transition-all):hover { background: var(--rtori-tint); color: var(--rtori-ink); }
.rtori :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtori-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtori__portrait { overflow: hidden; background: var(--rtori-tint); }
.rtori__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtori, .rtori * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtori .rtori__bg {
    background: var(--rtori-bg-fallback, var(--rtori-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtori .rtori__bg { background: var(--rtori-bg-fallback, var(--rtori-bg-fill)); }
}

.rtori__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtori-bg-fill);
  border: var(--rtori-bg-border, 0);
  -webkit-backdrop-filter: var(--rtori-blur);
  backdrop-filter: var(--rtori-blur);
  box-shadow: var(--rtori-bg-edge);
}

/* 구조: 동양풍 */

.rtori.rtori { display: grid; }
.rtori {
  grid-template-columns: auto minmax(0, 1fr);
  max-width: 52rem;
  margin: 0 auto;
  border-left: 1px solid var(--rtori-line);
  border-right: 1px solid var(--rtori-line);
  box-shadow: 0 6px 20px var(--rtori-shadow);
}
/* 한지 결과 흐림을 바탕 층(__bg)에만 두어 글래스에서도 종이 결이 깨끗하게 비칩니다. */
.rtori .rtori__bg {
  background:
    var(--rtori-bg-sheen),
    repeating-linear-gradient(115deg, var(--rtori-fiber) 0 1px, transparent 1px 9px),
    repeating-linear-gradient(25deg, var(--rtori-fiber) 0 1px, transparent 1px 13px),
    var(--rtori-paper);
  box-shadow:
    var(--rtori-bg-edge),
    inset 0 0 18px color-mix(in srgb, var(--rtori-line) 24%, transparent);
}
/* 족자의 위아래 가로대와 양 끝 축두 */
.rtori::before, .rtori::after {
  content: "";
  position: absolute;
  left: -.55rem;
  right: -.55rem;
  height: clamp(7px, 1.15vw, 11px);
  background:
    linear-gradient(90deg, var(--rtori-accent) 0 .85rem, transparent .85rem, transparent calc(100% - .85rem), var(--rtori-accent) calc(100% - .85rem)),
    var(--rtori-rod);
  border-radius: 999px;
  box-shadow: 0 2px 6px var(--rtori-shadow);
  pointer-events: none;
}
.rtori::before { top: calc(clamp(7px, 1.15vw, 11px) / -2); }
.rtori::after { bottom: calc(clamp(7px, 1.15vw, 11px) / -2); }
.rtori__band {
  display: flex;
  justify-content: center;
  padding: 1.35rem .5rem;
  background: var(--rtori-band);
  color: var(--rtori-band-ink);
  border-right: 1px solid var(--rtori-line);
}
.rtori__name {
  writing-mode: vertical-rl;
  font-family: var(--rtori-font-display);
  font-size: 1.15em;
  letter-spacing: .3em;
  white-space: nowrap;
}
.rtori--user .rtori__band { background: var(--rtori-band-user); }
.rtori__main { min-width: 0; padding: 1.35rem clamp(1.05rem, 4vw, 2.1rem) 1.1rem; }
.rtori__portrait {
  float: right;
  width: var(--rtori-seal-w);
  aspect-ratio: 1;
  margin: 0 0 .75rem 1.05rem;
  padding: clamp(2px, .4vw, 4px);
  border: clamp(2px, .45vw, 4px) double var(--rtori-accent);
  border-radius: .3rem;
  background: var(--rtori-paper);
  box-shadow: 0 3px 10px var(--rtori-shadow);
}
.rtori__portrait > * { border-radius: .15rem !important; }
.rtori { --rtori-seal-w: clamp(3.2rem, 10%, 5.2rem); }
.rtori--user { --rtori-seal-w: clamp(2.6rem, 7%, 3.6rem); }
.rtori__content::after { content: ""; display: block; clear: both; }
.rtori__footer { clear: both; margin-top: .85rem; padding-top: .55rem; border-top: 1px solid var(--rtori-line); font-size: .85em; }
@media (max-width: 520px) {
  .rtori { grid-template-columns: minmax(0, 1fr); }
  .rtori__band { justify-content: flex-start; padding: .48rem 1rem; border-right: 0; border-bottom: 1px solid var(--rtori-line); }
  .rtori__name { writing-mode: horizontal-tb; letter-spacing: .15em; }
}

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (글래스) ── */
.rtori {
  --rtori-blur: blur(16px) saturate(1.3);
  --rtori-bg-sheen: radial-gradient(120% 80% at 0% 0%, rgba(255, 255, 255, .13), transparent 54%), linear-gradient(165deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015) 68%);
  --rtori-bg-edge: 0 14px 36px -14px rgba(0, 0, 0, .52), inset 0 1px 0 rgba(255, 255, 255, .24), inset 0 0 0 1px rgba(255, 255, 255, .13);
  --rtori-bg-fallback: rgba(16, 18, 26, .88);
  --rtori-paper: rgba(16, 16, 20, .44);
  --rtori-fiber: rgba(255, 255, 255, .025);
  --rtori-rod: linear-gradient(rgba(255, 255, 255, .38), rgba(255, 255, 255, .14));
  --rtori-band: rgba(255, 255, 255, .12);
  --rtori-band-user: rgba(255, 255, 255, .07);
  --rtori-band-ink: #f2eee5;
  --rtori-ink: #efebe3;
  --rtori-strong: #ffffff;
  --rtori-muted: rgba(232, 228, 220, .68);
  --rtori-accent: #e2bfae;
  --rtori-dialog: #ffffff;
  --rtori-shadow: rgba(0, 0, 0, .28);
  --rtori-line: rgba(255, 255, 255, .15);
  --rtori-tint: rgba(255, 255, 255, .08);
  --rtori-edit-bg: rgba(10, 11, 15, .52);
}
